def cargar_acuerdos(apps, schema_editor):
    """Precarga los tres acuerdos vigentes y sus puntos (core/data/acuerdos_sindicales.json)."""
    Acuerdo = apps.get_model('core', 'AcuerdoSindical')
    Punto = apps.get_model('core', 'PuntoAcuerdo')
    if Acuerdo.objects.exists():
        return
    data = json.loads((Path(__file__).resolve().parent.parent / 'data' / 'acuerdos_sindicales.json').read_text(encoding='utf-8'))
    for item in data['acuerdos']:
        acuerdo = Acuerdo.objects.create(
            numero=item['numero'], titulo=item['titulo'], organizacion=data['organizacion'],
            fecha_firma=item['fecha_firma'], acto_adopcion=item['acto_adopcion'], vigente=True,
            notas=data['fuente'],
        )
        for punto in item['puntos']:
            Punto.objects.create(acuerdo=acuerdo, **punto)


